static int boltffi_python_wire_u64(PyObject *value, PyObject **out_wire, const uint8_t **out_ptr, uintptr_t *out_len) {
    uint64_t parsed = 0;
    uint8_t bytes[8];
    if (!boltffi_python_parse_u64(value, &parsed)) {
        return 0;
    }
    boltffi_python_write_u64_le(bytes, parsed);
    return boltffi_python_wire_fixed(bytes, 8, out_wire, out_ptr, out_len);
}





static int boltffi_python_wire_optional_u64(PyObject *value, PyObject **out_wire, const uint8_t **out_ptr, uintptr_t *out_len) {
    PyObject *payload = NULL;
    const uint8_t *payload_ptr = NULL;
    uintptr_t payload_len = 0;
    PyObject *wire = NULL;
    if (value == Py_None) {
        uint8_t tag[1] = {0};
        return boltffi_python_wire_fixed(tag, 1, out_wire, out_ptr, out_len);
    }
    if (!boltffi_python_wire_u64(value, &payload, &payload_ptr, &payload_len)) {
        return 0;
    }
    if (payload_len > (uintptr_t)PY_SSIZE_T_MAX - 1) {
        Py_DECREF(payload);
        PyErr_SetString(PyExc_OverflowError, "optional scalar payload is too large");
        return 0;
    }
    wire = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)(payload_len + 1));
    if (wire == NULL) {
        Py_DECREF(payload);
        return 0;
    }
    uint8_t *bytes = (uint8_t *)PyBytes_AS_STRING(wire);
    bytes[0] = 1;
    if (payload_len > 0) {
        memcpy(bytes + 1, payload_ptr, (size_t)payload_len);
    }
    Py_DECREF(payload);
    *out_wire = wire;
    *out_ptr = bytes;
    *out_len = payload_len + 1;
    return 1;
}














static int boltffi_python_wire_f64(PyObject *value, PyObject **out_wire, const uint8_t **out_ptr, uintptr_t *out_len) {
    double parsed = 0.0;
    uint64_t bits = 0;
    uint8_t bytes[8];
    if (!boltffi_python_parse_f64(value, &parsed)) {
        return 0;
    }
    memcpy(&bits, &parsed, sizeof(bits));
    boltffi_python_write_u64_le(bytes, bits);
    return boltffi_python_wire_fixed(bytes, 8, out_wire, out_ptr, out_len);
}

